export const getCatalogItem = (categorySlug, index, imgUrl) => {
  // 1. Direct Image Match by filename or URL
  if (imgUrl) {
    const filename = typeof imgUrl === 'string' ? imgUrl.split('/').pop() : '';
    if (filename && SPACES_IMAGE_CATALOG[filename]) {
      return SPACES_IMAGE_CATALOG[filename];
    }
    if (filename && SPACES_IMAGE_CATALOG[categorySlug]?.[filename]) {
      return SPACES_IMAGE_CATALOG[categorySlug][filename];
    }
  }

  // 2. Category list fallback by index
  const list = SPACES_CATALOG[categorySlug];
  if (Array.isArray(list) && list.length > 0) {
    const safeIdx = typeof index === 'number' && index >= 0 ? index % list.length : 0;
    return list[safeIdx];
  }

  // 3. Ultra-safe generic fallback
  return {
    title: 'Bespoke Architectural Configuration',
    layoutType: 'Custom Layout',
    materialTag: 'Premium Engineered Materials • Concealed Hardware',
    description: 'Custom interior joinery engineered to millimeter accuracy with premium finishes and concealed soft-close fittings.'
  };
};

export default SPACES_CATALOG;
